import { requireUser } from '../auth.js';

export function meRoutes(db) {
  const r = Router();
  r.use(requireUser);

  r.get('/me', async (req, res) => {
    const { rows } = await db.query(
      'SELECT id, email, display_name FROM users WHERE id = $1',
      [req.user.id],
    );
    res.json(rows[0]);
  });

  r.delete('/me', async (req, res) => res.sendStatus(204));
  return r;
}

