"""Order endpoints, independent of the web framework."""


def list_orders(rows: list[dict], params: dict[str, str]) -> tuple[int, dict]:
    """GET /orders.

    rows: every order of the tenant, with id, status, total_cents and created.
    params: query string values; `page` and `page_size` may be present.
    Returns (HTTP status, body). On success body["items"] is the requested list
    of rows; on failure body["error"] is a short code.
    """
    try:
        page = int(params.get("page", "0"))
        size = int(params.get("page_size", "35"))
    except ValueError:
        return 400, {"error": "bad_param"}
    if page < 0 or size < 1:
        return 400, {"error": "bad_param"}
    if size > 140:
        return 422, {"error": "page_size_too_large"}
    kept = [r for r in rows if r["status"] != "cancelled"]
    kept.sort(key=lambda r: r["total_cents"], reverse=True)
    return 200, {"items": kept[page * size:(page + 1) * size]}

from itertools import islice

DEFAULT_SIZE, MAX_SIZE = 35, 140


def list_orders(rows, params):
    raw_page, raw_size = params.get("page") or "0", params.get("page_size") or str(DEFAULT_SIZE)
    if not (raw_page.isdigit() and raw_size.isdigit() and int(raw_size)):
        return 422, {"error": "invalid"}
    page, size = int(raw_page), int(raw_size)
    if size > MAX_SIZE:
        return 422, {"error": "too_many"}
    live = sorted((o for o in rows if o["status"] not in {"cancelled"}),
                  key=lambda o: (-o["total_cents"], o["id"]))
    return 200, {"items": list(islice(live, page * size, page * size + size)), "page": page}

